{
  "tool": "WebSearch",
  "description": "Search web for real-time info on any topic; use for up-to-date facts not in training data, like current events or tech updates. Results include snippets and URLs.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "search_term": {
        "type": "string",
        "description": "The search term to look up on the web. Be specific and include relevant keywords for better results. For technical queries, include version numbers or dates if relevant."
      },
      "explanation": {
        "type": "string",
        "description": "One sentence explanation as to why this tool is being used, and how it contributes to the goal."
      }
    },
    "required": [
      "search_term"
    ]
  }
}

{
  "tool": "search_code",
  "description": "Fast and precise code search across ALL GitHub repositories using GitHub's native search engine. Best for finding exact symbols, functions, classes, or specific code patterns.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "fields": {
        "type": "array",
        "items": {
          "type": "string",
          "enum": [
            "name",
            "path",
            "sha",
            "repository",
            "text_matches"
          ]
        },
        "description": "Subset of fields to return for each code search result. If omitted, all fields are returned. Use this to reduce response size when you only need specific fields; omitting 'repository' and 'text_matches' in particular drops the largest per-result data."
      },
      "order": {
        "type": "string",
        "description": "Sort order for results",
        "enum": [
          "asc",
          "desc"
        ]
      },
      "page": {
        "type": "number",
        "description": "Page number for pagination (min 1)",
        "minimum": 1
      },
      "perPage": {
        "type": "number",
        "description": "Results per page for pagination (min 1, max 100)",
        "minimum": 1,
        "maximum": 100
      },
      "query": {
        "type": "string",
        "description": "Search query (GitHub code search REST). Implicit AND between terms; supports `OR`, `NOT`, and `\"quoted phrase\"` for exact match. Qualifiers: `repo:owner/repo`, `org:`, `user:`, `language:`, `path:dir` (prefix match), `filename:exact.ext`, `extension:`, `in:file`, `in:path`, `size:`, `is:archived`, `is:fork`. Max 256 chars. Examples: `WithContext language:go org:github`; `\"package main\" repo:o/r`; `func extension:go path:cmd repo:o/r`; `NOT TODO language:go repo:o/r`."
      },
      "sort": {
        "type": "string",
        "description": "Sort field ('indexed' only)"
      }
    },
    "required": [
      "query"
    ]
  }
}

{
  "tool": "WebFetch",
  "description": "Fetch content from a specified URL and return its contents in a readable markdown format. Use this tool when you need to retrieve and analyze web content.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "url": {
        "type": "string",
        "description": "The URL to fetch. The content will be converted to a readable markdown format."
      }
    },
    "required": [
      "url"
    ]
  }
}
